const request = $('Receive Dynamic Case').first().json.body ?? $('Receive Dynamic Case').first().json;
const c = request.case_result ?? {};
const bool = (v) => v === true || String(v).toLowerCase() === 'true' || String(v) === '1';
const norm = (v) => String(v ?? '').trim().toLowerCase();
const requiredService = norm(c.service_required);
const requiredArea = norm(c.service_area);
const maxDistance = Number(c.max_distance_km ?? 10);
const testMode = bool(request.test_mode);
const testPhone = String(request.test_worker_phone ?? '').trim();

const candidates = $input.all().map((item) => item.json).filter((w) => {
  const available = bool(w.available);
  const optedIn = bool(w.opted_in);
  const statusOk = ['available', 'ready'].includes(norm(w.assignment_status));
  const serviceOk = !requiredService || norm(w.service_type) === requiredService;
  const areaOk = !requiredArea || norm(w.area) === requiredArea;
  const distanceOk = Number(w.distance_km ?? 999) <= maxDistance;
  return available && optedIn && statusOk && serviceOk && areaOk && distanceOk;
}).map((w) => {
  const rating = Number(w.rating ?? 0);
  const distance = Number(w.distance_km ?? 999);
  const acceptanceRate = Number(w.acceptance_rate ?? 0);
  const workload = Number(w.current_workload ?? 0);
  const score = Math.round((rating * 20 + acceptanceRate * 20 - distance * 5 - workload * 10) * 100) / 100;
  return {
    worker_id: String(w.worker_id),
    worker_name: String(w.worker_name),
    worker_phone: testMode ? testPhone : String(w.phone),
    estimated_arrival: String(w.estimated_arrival ?? 'ETA pending'),
    score,
    rating,
    distance_km: distance,
    acceptance_rate: acceptanceRate,
    rationale: 'Eligible, opted in, available, service/area match; ranked by rating, acceptance, distance and workload',
  };
}).sort((a, b) => b.score - a.score || a.distance_km - b.distance_km || b.rating - a.rating || a.worker_id.localeCompare(b.worker_id));

const selected = candidates[0] ?? null;
return [{ json: {
  selection_status: selected ? 'candidate_selected' : 'no_candidates',
  case_id: String(c.case_id ?? ''),
  customer_email: String(request.test_customer_email ?? ''),
  manager_email: String(request.test_manager_email ?? ''),
  service_type: String(c.service_required ?? ''),
  area: String(c.service_area ?? ''),
  candidate_queue_json: JSON.stringify(candidates),
  current_candidate_index: selected ? 0 : -1,
  current_worker_id: selected?.worker_id ?? '',
  current_worker_name: selected?.worker_name ?? '',
  current_worker_phone: selected?.worker_phone ?? '',
  current_eta: selected?.estimated_arrival ?? '',
  assignment_status: selected ? 'assignment_pending' : 'no_candidates',
  selected_score: selected?.score ?? null,
  eligible_candidate_count: candidates.length,
  updated_at: new Date().toISOString(),
} }];

const p = $json.body ?? $json;
const raw = String(p.ButtonPayload || p.ButtonText || p.Body || '').trim();
const normalized = raw.toUpperCase();
let decision = 'unrecognized';
if (['ACCEPT', 'ACCEPT ASSIGNMENT', 'YES', 'A', 'C', 'CONFIRM'].includes(normalized)) decision = 'accepted';
if (['DECLINE', 'DECLINE ASSIGNMENT', 'NO', 'D', 'R', 'RESCHEDULE'].includes(normalized)) decision = 'declined';
const workerPhone = String(p.From || '').replace(/^whatsapp:/i, '');
return [{ json: { decision, raw_reply: raw, worker_phone: workerPhone, inbound_message_sid: p.MessageSid || p.SmsMessageSid || '', received_at: new Date().toISOString() } }];

