const state = $('Find Pending Dynamic Case').first().json;
let queue = [];
try { queue = JSON.parse(state.candidate_queue_json || '[]'); } catch (e) { queue = []; }
const nextIndex = Number(state.current_candidate_index ?? -1) + 1;
const next = queue[nextIndex] ?? null;
return [{ json: {
  ...state,
  current_candidate_index: nextIndex,
  current_worker_id: next?.worker_id ?? '',
  current_worker_name: next?.worker_name ?? '',
  current_worker_phone: next?.worker_phone ?? '',
  current_eta: next?.estimated_arrival ?? '',
  selected_score: next?.score ?? null,
  has_next_candidate: Boolean(next),
  assignment_status: next ? 'assignment_pending' : 'candidates_exhausted',
  updated_at: new Date().toISOString(),
} }];
